export type InputReactorViskoOrbisDynamic =
  | {
      command: 'pause'
      data: object
    }
  | {
      command: 'reset'
      data: object
    }
  | {
      command: 'start'
      data: object
    }
  | {
      command: 'resume'
      data: object
    }
  | {
      command: 'set_seed'
      data: {
        /**
         * @description Seed for the noise the first chunk is sampled from. Must be a non-negative integer; the model never draws its own seed, so the same seed with the same prompts reproduces the same video. Read once when `start` fires — later changes take effect only after `reset` followed by a new `start`.
         * @minimum 0
         * @default 42
         * @type integer | undefined
         */
        seed?: number
      }
    }
  | {
      command: 'set_image'
      data: {
        /**
         * @description Starting frame, uploaded via the Reactor presigned-URL protocol. PNG or JPEG. Any size — it is resized to the model's 640x368 without cropping, so a frame of a different aspect ratio is squashed rather than trimmed.
         *
         * Format: `reactor-upload-reference`
         * @default null
         * @type object | undefined
         */
        image?: ReactorUploadReference
      }
    }
  | {
      command: 'set_prompt'
      data: {
        /**
         * @description Natural-language description of the scene to generate. Replaces the previously active prompt. Applied on the next chunk when generating; otherwise takes effect when `start` fires.
         * @default ''
         * @type string | undefined
         */
        prompt?: string
        /**
         * @description Send this prompt to the model exactly as written. This deployment prepares `set_prompt` text server-side first; true skips that, and the text sent is what conditions generation, byte for byte — for prompts already authored the way the model wants them. Decided per call, so prepared and verbatim prompts mix freely in one session — a prompt sent this way still carries its characters and setting into the next one. Inert on a deployment that prepares nothing, where every prompt is already verbatim.
         * @default false
         * @type boolean | undefined
         */
        passthrough?: boolean
      }
    }
  | {
      command: 'set_resolution'
      data: {
        /**
         * @description One of the deployment's offered resolutions, exactly as listed in the `state` snapshot's `available_resolutions` — `native` is the model's generated geometry, the named tiers are upscaler-delivered (1080p = 1920x1080, 2k = 2560x1440, 4k = 3840x2160).
         * @default ''
         * @type string | undefined
         */
        resolution?: string
      }
    }
  | {
      command: 'set_audio_prompt'
      data: {
        /**
         * @description What the scene should SOUND like — instruments, voices, materials, ambience. Not a description of what is on screen: sending a scene description here makes the audio worse than leaving it empty. Keep it to about one sentence; roughly the first 128 tokens are used and the rest is dropped without warning. Example: "Acoustic guitar strums a rhythmic melody, with soft finger noise on the strings and quiet room ambience." Empty clears it, and the audio is then generated from the picture alone.
         * @default ''
         * @type string | undefined
         */
        prompt?: string
      }
    }
  | {
      command: 'set_audio_enabled'
      data: {
        /**
         * @description True to generate sound on `main_audio` (the default), false to skip the audio model and deliver silence from the next `start` on.
         * @default true
         * @type boolean | undefined
         */
        audio_enabled?: boolean
      }
    }

